<script setup lang="ts">
import { computed, ref } from 'vue'
import {
  ChevronRight, CircleHelp, Clipboard, DatabaseBackup, FolderTree, Info, KeyRound, RefreshCw, ShieldCheck,
} from '@lucide/vue'
import { useAppStore } from '@/stores/app-store'
import { copyText } from '@/infrastructure/platform/clipboard'
import wechatQr from '@/assets/wechat-qr.png'
import AppDialog from '@/components/AppDialog.vue'

const store = useAppStore()
const aboutOpen = ref(false)
const appVersion = import.meta.env.VITE_APP_VERSION ?? '1.0.4'
const licenseLabel = computed(() => ({
  active: '已激活', expired: '授权已过期', invalid: '授权异常', unactivated: '输入授权码解锁记账功能',
}[store.license.kind]))
const backupSubtitle = computed(() => {
  if (store.settings.backupReminderEnabled === false) return '导出、恢复、格式化和备份提醒'
  const at = store.settings.lastBackupAt
  if (!at) return '导出、恢复、格式化；从未备份'
  const date = new Date(at)
  if (Number.isNaN(date.getTime())) return '导出、恢复、格式化；从未备份'
  return `导出、恢复、格式化；上次备份 ${date.toLocaleString('zh-CN', { hour12: false })}`
})
const rows = [
  { title: '授权码', route: '/settings/license', icon: KeyRound, subtitle: () => licenseLabel.value },
  { title: '分类管理', route: '/settings/categories', icon: FolderTree, subtitle: () => '管理收入和支出分类' },
  { title: '数据备份与恢复', route: '/settings/backup', icon: DatabaseBackup, subtitle: () => backupSubtitle.value },
  { title: '更新版本', route: '/settings/update', icon: RefreshCw, subtitle: () => '只在点击后联网检查' },
]

async function copyWechat(): Promise<void> {
  try {
    await copyText('zdx-lhl')
    store.notify('微信号已复制', 'success')
  } catch (cause) {
    store.notify(cause instanceof Error ? cause.message : '复制失败', 'error')
  }
}
</script>

<template>
  <main class="page settings-page">
    <section class="settings-list card">
      <RouterLink v-for="row in rows" :key="row.route" :to="row.route" class="settings-row">
        <span class="row-icon"><component :is="row.icon" :size="22" /></span>
        <span class="row-main"><strong>{{ row.title }}</strong><small>{{ row.subtitle() }}</small></span>
        <ChevronRight :size="20" aria-hidden="true" />
      </RouterLink>
    </section>

    <section class="privacy-card card">
      <ShieldCheck :size="26" aria-hidden="true" />
      <div><h2>数据只保存在本机</h2><p>记账、统计、授权和备份均可离线使用。账单不会上传到服务器；只有你点击“更新版本”时才连接更新地址。</p></div>
    </section>

    <button class="about-row card" type="button" @click="aboutOpen = true"><Info :size="21" /><span>关于随手记</span><ChevronRight :size="20" /></button>

    <p class="version">版本 {{ appVersion }}</p>
  </main>

  <AppDialog :open="aboutOpen" title="关于随手记" @close="aboutOpen = false">
    <div class="about-content">
      <CircleHelp :size="42" aria-hidden="true" />
      <h3>随手记</h3>
      <p>本地优先、离线可用的个人记账工具。</p>
      <p>如需帮助或获取授权码，请联系作者。</p>
      <img :src="wechatQr" alt="联系作者的微信二维码" />
      <button class="button secondary" type="button" @click="copyWechat"><Clipboard :size="18" />复制微信号 zdx-lhl</button>
    </div>
  </AppDialog>
</template>

